# (чтение) 1030 по банковским счетам ANESCOM (без GREENTE) на конец 25.10.2026 и помесячные обороты 04–10.2026 по счёту 2209.
D = datetime.datetime(2026, 10, 26, 5, 0)   # конец 25.10 с учётом сдвига COM
for r in q('ВЫБРАТЬ О.Субконто1 КАК Б, О.Организация КАК Орг, О.СуммаОстаток КАК С ИЗ РегистрБухгалтерии.{REG}.Остатки(&Д, Счет.Код ПОДОБНО "1030%", , ) КАК О', Д=D):
    print(f"  {s(r['Орг'])[:30]:30s} | {s(r['Б'])[:55]:55s} | {float(r['С'] or 0):>18,.2f}")
print('банк Halyk 2209 на 25.10.2026: 7 240 383,30 | на 01.04.2026: 1 000 000,00')
for r in q('ВЫБРАТЬ НАЧАЛОПЕРИОДА(О.Период, МЕСЯЦ) КАК М, СУММА(О.СуммаОборотДт) КАК Дт, СУММА(О.СуммаОборотКт) КАК Кт ИЗ РегистрБухгалтерии.{REG}.Обороты(&Н, &Д, Месяц, Счет.Код ПОДОБНО "1030%", , Субконто1.Наименование ПОДОБНО "%2209%" И НЕ Организация.Префикс = "GT", , ) КАК О СГРУППИРОВАТЬ ПО НАЧАЛОПЕРИОДА(О.Период, МЕСЯЦ) УПОРЯДОЧИТЬ ПО М', Н=datetime.datetime(2026, 4, 1, 5, 0), Д=D):
    print(f"  {str(r['М'])[:7]} Дт {float(r['Дт'] or 0):>16,.2f}  Кт {float(r['Кт'] or 0):>16,.2f}")
